import { Suspense, lazy, useEffect, useMemo, useRef, useState } from "react";
import { FluentProvider } from "@fluentui/react-components";
import { ja } from "./strings/ja";
import { hsLightTheme, hsDarkTheme } from "./theme/fluentTheme";
import { useThemeMode } from "./theme/useThemeMode";
import { AppShell } from "./components/AppShell";
import { TitleBar } from "./components/TitleBar";
import { CommandBar } from "./components/CommandBar";
import { WaveformView } from "./components/WaveformView";
import { ScoreWorkspace } from "./components/ScoreWorkspace";
import { PropertiesPanel } from "./components/PropertiesPanel";
import { TransportBar } from "./components/TransportBar";
import { StatusBar } from "./components/StatusBar";
import { SettingsView } from "./components/SettingsView";
import type { PitchView } from "./components/PitchSegmented";
import {
  createCommandRegistry,
  createCommandSurface,
  type CommandContext,
  type CommandSnapshot,
} from "./commands/registry";
import { KeyboardDispatcher } from "./keyboard/dispatcher";
import { useCommandKeyboard } from "./keyboard/useCommandKeyboard";
import { cycleFocusZone } from "./focus/zones";
import { getShellInfo } from "./tauri/bridge";

type View = "workspace" | "settings";

/** "#/dev/gallery" — dev-only internal component gallery (UI-010). */
const GALLERY_HASH = "#/dev/gallery";
// Lazy so the gallery (and its Fluent imports) stay out of the prod bundle.
const DevGallery = import.meta.env.DEV
  ? lazy(() => import("./dev/Gallery"))
  : null;

/** Japanese display name for a focus zone (for status announcements). */
function zoneName(id: string): string {
  const names: Record<string, string> = ja.commandFeedback.zoneNames;
  return names[id] ?? id;
}

/**
 * UI-001 spike shell driven by the UI-012 command architecture
 * (GUI_UX_SPEC §22/§23). Screen state is fixed to EMPTY (§27): no audio, no
 * score, no engine. The shell proves layout, theming, Japanese copy,
 * keyboard/focus behavior, IPC plumbing and the CSP/capability baseline
 * before real features are wired in.
 */
export default function App() {
  const { mode, resolved, select } = useThemeMode();
  const [view, setView] = useState<View>("workspace");
  const [pitch, setPitch] = useState<PitchView>("concert");
  const [statusMessage, setStatusMessage] = useState<string>(ja.status.ready);
  const [shellDetail, setShellDetail] = useState<string | undefined>(
    ja.status.shellInfoLoading,
  );
  const [hash, setHash] = useState(() => window.location.hash);

  // The registry is static: predicates read the snapshot, not React state.
  const registry = useMemo(() => createCommandRegistry(), []);

  // EMPTY state (§27): nothing loaded yet — transport/edit/export commands
  // evaluate disabled from this snapshot on every surface at once.
  const snapshot = useMemo<CommandSnapshot>(
    () => ({
      hasAudio: false,
      hasScore: false,
      isTranscribing: false,
      isPlaying: false,
      loopEnabled: false,
      pitch,
      canUndo: false,
      canRedo: false,
      hasSelection: false,
      reviewOpen: false,
      reviewCount: 0,
      view,
    }),
    [pitch, view],
  );

  const ctx = useMemo<CommandContext>(
    () => ({
      openAudio: () => setStatusMessage(ja.status.spikeNoFileOpen),
      transcribe: () => setStatusMessage(ja.commandFeedback.notImplemented),
      togglePlayPause: () =>
        setStatusMessage(ja.commandFeedback.notImplemented),
      stop: () => setStatusMessage(ja.commandFeedback.notImplemented),
      jumpBack: () => setStatusMessage(ja.commandFeedback.notImplemented),
      jumpForward: () => setStatusMessage(ja.commandFeedback.notImplemented),
      seekToStart: () => setStatusMessage(ja.commandFeedback.notImplemented),
      seekToEnd: () => setStatusMessage(ja.commandFeedback.notImplemented),
      toggleLoop: () => setStatusMessage(ja.commandFeedback.notImplemented),
      setPitchView: (v) => {
        setPitch(v);
        setStatusMessage(
          v === "concert"
            ? ja.commandFeedback.pitchConcert
            : ja.commandFeedback.pitchHornF,
        );
      },
      openReview: () => setStatusMessage(ja.commandFeedback.notImplemented),
      reviewNext: () => setStatusMessage(ja.commandFeedback.notImplemented),
      reviewPrevious: () =>
        setStatusMessage(ja.commandFeedback.notImplemented),
      undo: () => setStatusMessage(ja.commandFeedback.notImplemented),
      redo: () => setStatusMessage(ja.commandFeedback.notImplemented),
      openExport: () => setStatusMessage(ja.commandFeedback.notImplemented),
      zoomScoreIn: () => setStatusMessage(ja.commandFeedback.notImplemented),
      zoomScoreOut: () => setStatusMessage(ja.commandFeedback.notImplemented),
      zoomScoreFit: () => setStatusMessage(ja.commandFeedback.notImplemented),
      clearSelection: () =>
        setStatusMessage(ja.commandFeedback.notImplemented),
      openSettings: () => setView("settings"),
      // F6 / Shift+F6 region cycling (§22) — the only fully-working
      // transport-independent commands in the spike.
      focusNextRegion: () => {
        const zone = cycleFocusZone(1);
        if (zone) {
          setStatusMessage(ja.commandFeedback.focusMoved(zoneName(zone)));
        }
      },
      focusPreviousRegion: () => {
        const zone = cycleFocusZone(-1);
        if (zone) {
          setStatusMessage(ja.commandFeedback.focusMoved(zoneName(zone)));
        }
      },
      announce: setStatusMessage,
    }),
    [],
  );

  // The dispatcher reads the snapshot lazily per key event, so it must see
  // the latest render's value even though the listener is stable.
  const snapshotRef = useRef(snapshot);
  snapshotRef.current = snapshot;
  const dispatcher = useMemo(
    () =>
      new KeyboardDispatcher({
        registry,
        getSnapshot: () => snapshotRef.current,
        context: ctx,
      }),
    [registry, ctx],
  );
  useCommandKeyboard(dispatcher);

  // One render-scoped invocation surface shared by command bar, transport
  // and any other component — buttons never call services directly.
  const commands = useMemo(
    () => createCommandSurface(registry, ctx, snapshot),
    [registry, ctx, snapshot],
  );

  // Hash routing is only used for the internal dev gallery; the product
  // shell is a single workspace (GUI_UX_SPEC §2), not a page router.
  useEffect(() => {
    const onHashChange = () => setHash(window.location.hash);
    window.addEventListener("hashchange", onHashChange);
    return () => window.removeEventListener("hashchange", onHashChange);
  }, []);

  // Prove the JS↔Rust IPC channel early; populates the status area.
  useEffect(() => {
    let alive = true;
    getShellInfo().then((info) => {
      if (!alive) return;
      setShellDetail(
        info ? `v${info.version}` : undefined, // browser dev: no shell info
      );
      setStatusMessage(ja.status.ready);
    });
    return () => {
      alive = false;
    };
  }, []);

  const theme = resolved === "dark" ? hsDarkTheme : hsLightTheme;
  // Dev-only route: the gallery renders in place of the shell and never
  // appears in product navigation.
  const showGallery = DevGallery != null && hash === GALLERY_HASH;

  return (
    <FluentProvider theme={theme}>
      {showGallery ? (
        <Suspense fallback={null}>
          <DevGallery themeMode={mode} onThemeMode={select} />
        </Suspense>
      ) : (
        <AppShell>
          <TitleBar />
          {view === "settings" ? (
            <div className="hs-settings-wrap">
              <SettingsView
                themeMode={mode}
                onThemeMode={select}
                onBack={() => setView("workspace")}
              />
            </div>
          ) : (
            <>
              <CommandBar commands={commands} pitch={pitch} />
              <WaveformView />
              <div className="hs-main">
                <ScoreWorkspace
                  onOpenAudio={() => commands.invoke("file.openAudio")}
                />
                <PropertiesPanel />
              </div>
              <TransportBar commands={commands} />
            </>
          )}
          <StatusBar message={statusMessage} detail={shellDetail} />
        </AppShell>
      )}
    </FluentProvider>
  );
}

/**
 * Built-in command definitions (docs/GUI_UX_SPEC.md §7, §9, §14, §15, §22).
 *
 * This is the single source of truth: command bar buttons, menus, a future
 * command palette and the keyboard dispatcher all consume this list —
 * components never define their own shortcut handlers.
 *
 * Shortcut table (issue UI-012 / spec §9, §15, §22):
 *   Ctrl+O          open audio          F6 / Shift+F6   region cycle
 *   Space / K       play-pause          Ctrl+Z          undo
 *   Shift+Space     stop                Ctrl+Shift+Z    redo
 *   J / L           jump back/forward   Ctrl+E          export
 *   Home / End      start/end           Ctrl++ Ctrl+-   score zoom
 *   Ctrl+L          loop toggle         Ctrl+0          zoom to width
 *   Ctrl+1 / Ctrl+2 concert / F-horn    Esc             clear selection
 */

import { ja } from "../strings/ja";
import type { Command, CommandSnapshot } from "./types";

const hasAudio = (s: CommandSnapshot) => s.hasAudio;
const hasScore = (s: CommandSnapshot) => s.hasScore;
const canEditScore = (s: CommandSnapshot) => s.hasScore && !s.isTranscribing;

/**
 * All built-in commands. Order is the canonical listing order (command
 * palette / docs); `section` groups them for menus.
 */
export function createCommandDefinitions(): readonly Command[] {
  return [
    // ---- file ----
    {
      id: "file.openAudio",
      title: ja.commands.openAudio,
      section: "file",
      shortcuts: ["Ctrl+O"],
      run: (ctx) => ctx.openAudio(),
    },

    // ---- score ----
    {
      id: "score.transcribe",
      title: ja.commands.transcribe,
      section: "score",
      // §5: rewriting the canonical score mid-transcription is forbidden.
      isEnabled: (s) => s.hasAudio && !s.isTranscribing,
      run: (ctx) => ctx.transcribe(),
    },
    {
      id: "score.retranscribe",
      title: ja.commands.retranscribe,
      section: "score",
      // Same action as 採譜 once a score exists; the command bar relabels.
      isEnabled: (s) => s.hasScore && !s.isTranscribing,
      isVisible: (s) => s.hasScore,
      run: (ctx) => ctx.transcribe(),
    },
    {
      id: "score.zoomIn",
      title: ja.commands.zoomScoreIn,
      section: "score",
      // "+" needs Shift on US/JIS layouts; "Ctrl+=" is the unshifted twin.
      // The numpad "+" also arrives as key "+" so no extra binding is needed.
      shortcuts: ["Ctrl+=", "Ctrl++"],
      isEnabled: canEditScore,
      run: (ctx) => ctx.zoomScoreIn(),
    },
    {
      id: "score.zoomOut",
      title: ja.commands.zoomScoreOut,
      section: "score",
      shortcuts: ["Ctrl+-"],
      isEnabled: canEditScore,
      run: (ctx) => ctx.zoomScoreOut(),
    },
    {
      id: "score.zoomFit",
      title: ja.commands.zoomScoreFit,
      section: "score",
      shortcuts: ["Ctrl+0"],
      isEnabled: canEditScore,
      run: (ctx) => ctx.zoomScoreFit(),
    },

    // ---- transport (§9) ----
    {
      id: "transport.playPause",
      title: ja.commands.playPause,
      section: "transport",
      shortcuts: ["Space", "K"],
      isEnabled: hasAudio,
      run: (ctx) => ctx.togglePlayPause(),
    },
    {
      id: "transport.stop",
      title: ja.commands.stop,
      section: "transport",
      shortcuts: ["Shift+Space"],
      isEnabled: hasAudio,
      run: (ctx) => ctx.stop(),
    },
    {
      id: "transport.jumpBack",
      title: ja.commands.jumpBack,
      section: "transport",
      shortcuts: ["J"],
      allowRepeat: true, // holding J/L scrubs, like video editors
      isEnabled: hasAudio,
      run: (ctx) => ctx.jumpBack(),
    },
    {
      id: "transport.jumpForward",
      title: ja.commands.jumpForward,
      section: "transport",
      shortcuts: ["L"],
      allowRepeat: true,
      isEnabled: hasAudio,
      run: (ctx) => ctx.jumpForward(),
    },
    {
      id: "transport.seekStart",
      title: ja.commands.seekStart,
      section: "transport",
      shortcuts: ["Home"],
      isEnabled: hasAudio,
      run: (ctx) => ctx.seekToStart(),
    },
    {
      id: "transport.seekEnd",
      title: ja.commands.seekEnd,
      section: "transport",
      shortcuts: ["End"],
      isEnabled: hasAudio,
      run: (ctx) => ctx.seekToEnd(),
    },
    {
      id: "transport.toggleLoop",
      title: ja.commands.toggleLoop,
      section: "transport",
      shortcuts: ["Ctrl+L"],
      isEnabled: hasAudio,
      run: (ctx) => ctx.toggleLoop(),
    },

    // ---- view (§7: explicit pair, not a toggle) ----
    {
      id: "view.concertPitch",
      title: ja.commands.concertPitch,
      section: "view",
      shortcuts: ["Ctrl+1"],
      run: (ctx) => ctx.setPitchView("concert"),
    },
    {
      id: "view.hornF",
      title: ja.commands.hornF,
      section: "view",
      shortcuts: ["Ctrl+2"],
      run: (ctx) => ctx.setPitchView("hornF"),
    },

    // ---- review (§12) ----
    {
      id: "review.open",
      title: ja.commands.openReview,
      section: "review",
      isEnabled: (s) => s.hasScore && s.reviewCount > 0,
      isVisible: (s) => s.hasScore && s.reviewCount > 0,
      run: (ctx) => ctx.openReview(),
    },
    {
      id: "review.next",
      title: ja.commands.reviewNext,
      section: "review",
      isEnabled: (s) => s.reviewOpen,
      isVisible: (s) => s.reviewOpen,
      run: (ctx) => ctx.reviewNext(),
    },
    {
      id: "review.previous",
      title: ja.commands.reviewPrevious,
      section: "review",
      isEnabled: (s) => s.reviewOpen,
      isVisible: (s) => s.reviewOpen,
      run: (ctx) => ctx.reviewPrevious(),
    },

    // ---- edit (§14: every fix is a command) ----
    {
      id: "edit.undo",
      title: ja.commands.undo,
      section: "edit",
      shortcuts: ["Ctrl+Z"],
      isEnabled: (s) => s.canUndo,
      run: (ctx) => ctx.undo(),
    },
    {
      id: "edit.redo",
      title: ja.commands.redo,
      section: "edit",
      shortcuts: ["Ctrl+Shift+Z"],
      isEnabled: (s) => s.canRedo,
      run: (ctx) => ctx.redo(),
    },
    {
      id: "edit.clearSelection",
      title: ja.commands.clearSelection,
      section: "edit",
      shortcuts: ["Escape"],
      isEnabled: (s) => s.hasSelection,
      run: (ctx) => ctx.clearSelection(),
    },

    // ---- export ----
    {
      id: "export.open",
      title: ja.commands.export,
      section: "export",
      shortcuts: ["Ctrl+E"],
      isEnabled: hasScore,
      run: (ctx) => ctx.openExport(),
    },

    // ---- navigation / focus (§22: F6 cycles the major regions) ----
    {
      id: "nav.nextRegion",
      title: ja.commands.nextRegion,
      section: "nav",
      shortcuts: ["F6"],
      run: (ctx) => ctx.focusNextRegion(),
    },
    {
      id: "nav.previousRegion",
      title: ja.commands.previousRegion,
      section: "nav",
      shortcuts: ["Shift+F6"],
      run: (ctx) => ctx.focusPreviousRegion(),
    },

    // ---- app ----
    {
      id: "app.settings",
      title: ja.commands.settings,
      section: "app",
      run: (ctx) => ctx.openSettings(),
    },
  ];
}

/**
 * Command registry tests (issue UI-012 acceptance: "shortcut conflict test
 * exists", "all commands have Japanese labels").
 *
 * Pure logic — no DOM needed.
 */

import { describe, expect, it, vi } from "vitest";
import { ja } from "../strings/ja";
import { CommandRegistry, createCommandRegistry } from "./registry";
import type {
  Command,
  CommandContext,
  CommandSnapshot,
} from "./types";

const SNAPSHOT_EMPTY: CommandSnapshot = {
  hasAudio: false,
  hasScore: false,
  isTranscribing: false,
  isPlaying: false,
  loopEnabled: false,
  pitch: "concert",
  canUndo: false,
  canRedo: false,
  hasSelection: false,
  reviewOpen: false,
  reviewCount: 0,
  view: "workspace",
};

const SNAPSHOT_SCORE: CommandSnapshot = {
  ...SNAPSHOT_EMPTY,
  hasAudio: true,
  hasScore: true,
  canUndo: true,
  canRedo: true,
  hasSelection: true,
  reviewCount: 3,
};

function mockContext(): CommandContext & { calls: string[] } {
  const calls: string[] = [];
  const spy = (name: string) => vi.fn(() => calls.push(name));
  return {
    calls,
    openAudio: spy("openAudio"),
    transcribe: spy("transcribe"),
    togglePlayPause: spy("togglePlayPause"),
    stop: spy("stop"),
    jumpBack: spy("jumpBack"),
    jumpForward: spy("jumpForward"),
    seekToStart: spy("seekToStart"),
    seekToEnd: spy("seekToEnd"),
    toggleLoop: spy("toggleLoop"),
    setPitchView: spy("setPitchView"),
    openReview: spy("openReview"),
    reviewNext: spy("reviewNext"),
    reviewPrevious: spy("reviewPrevious"),
    undo: spy("undo"),
    redo: spy("redo"),
    openExport: spy("openExport"),
    zoomScoreIn: spy("zoomScoreIn"),
    zoomScoreOut: spy("zoomScoreOut"),
    zoomScoreFit: spy("zoomScoreFit"),
    clearSelection: spy("clearSelection"),
    openSettings: spy("openSettings"),
    focusNextRegion: spy("focusNextRegion"),
    focusPreviousRegion: spy("focusPreviousRegion"),
    announce: spy("announce"),
  };
}

describe("command definitions", () => {
  const registry = createCommandRegistry();

  it("covers every command required by UI-012 / GUI_UX_SPEC", () => {
    const ids = registry.list().map((c) => c.id);
    for (const required of [
      "file.openAudio",
      "score.transcribe",
      "transport.playPause",
      "transport.stop",
      "transport.jumpBack",
      "transport.jumpForward",
      "transport.toggleLoop",
      "view.concertPitch",
      "view.hornF",
      "review.next",
      "review.previous",
      "edit.undo",
      "edit.redo",
      "export.open",
      "score.zoomIn",
      "score.zoomOut",
      "score.zoomFit",
      "nav.nextRegion",
      "nav.previousRegion",
    ]) {
      expect(ids).toContain(required);
    }
  });

  it("ships with zero shortcut conflicts", () => {
    expect(registry.detectConflicts()).toEqual([]);
  });

  it("every command has a non-empty Japanese title", () => {
    const known = new Set<string>(Object.values(ja.commands));
    for (const command of registry.list()) {
      expect(command.title.length).toBeGreaterThan(0);
      // Titles come from the shared copy module, not ad-hoc strings.
      expect(known.has(command.title)).toBe(true);
    }
  });

  it("initial bindings match the spec table (§9, §15, §22)", () => {
    const shortcutOf = (id: string) =>
      registry.get(id)?.shortcuts ?? [];
    expect(shortcutOf("file.openAudio")).toContain("Ctrl+O");
    expect(shortcutOf("transport.playPause")).toEqual(
      expect.arrayContaining(["Space", "K"]),
    );
    expect(shortcutOf("transport.stop")).toContain("Shift+Space");
    expect(shortcutOf("transport.jumpBack")).toContain("J");
    expect(shortcutOf("transport.jumpForward")).toContain("L");
    expect(shortcutOf("transport.toggleLoop")).toContain("Ctrl+L");
    expect(shortcutOf("view.concertPitch")).toContain("Ctrl+1");
    expect(shortcutOf("view.hornF")).toContain("Ctrl+2");
    expect(shortcutOf("edit.undo")).toContain("Ctrl+Z");
    expect(shortcutOf("edit.redo")).toContain("Ctrl+Shift+Z");
    expect(shortcutOf("export.open")).toContain("Ctrl+E");
    expect(shortcutOf("score.zoomIn")).toEqual(
      expect.arrayContaining(["Ctrl+=", "Ctrl++"]),
    );
    expect(shortcutOf("score.zoomOut")).toContain("Ctrl+-");
    expect(shortcutOf("score.zoomFit")).toContain("Ctrl+0");
    expect(shortcutOf("nav.nextRegion")).toContain("F6");
    expect(shortcutOf("nav.previousRegion")).toContain("Shift+F6");
  });
});

describe("conflict detection", () => {
  const cmd = (over: Partial<Command> & { id: string }): Command => ({
    title: "テスト",
    section: "app",
    run: () => undefined,
    ...over,
  });

  it("detects two commands bound to the same chord", () => {
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Ctrl+P"] }),
      cmd({ id: "b.two", shortcuts: ["Ctrl+P"] }),
    ]);
    expect(registry.detectConflicts()).toEqual([
      { shortcut: "Ctrl+P", commandIds: ["a.one", "b.two"] },
    ]);
  });

  it("normalizes bindings before comparing (Ctrl+shift+p == Ctrl+Shift+P)", () => {
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Ctrl+Shift+P"] }),
      cmd({ id: "b.two", shortcuts: ["ctrl+shift+p"] }),
    ]);
    expect(registry.detectConflicts()).toHaveLength(1);
  });

  it("detects multi-chord sequence collisions", () => {
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Ctrl+K Ctrl+C"] }),
      cmd({ id: "b.two", shortcuts: ["Ctrl+K Ctrl+C"] }),
    ]);
    expect(registry.detectConflicts()).toHaveLength(1);
  });

  it("does not flag two bindings owned by the same command", () => {
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Space", "K"] }),
      cmd({ id: "b.two", shortcuts: ["L"] }),
    ]);
    expect(registry.detectConflicts()).toEqual([]);
  });

  it("does not flag a chord vs. a longer sequence sharing its prefix", () => {
    // "Ctrl+K" alone and "Ctrl+K Ctrl+C" coexist: the single chord fires
    // immediately, so this is intentionally strict — they DO conflict at
    // the dispatcher level… except the first chord completes its binding
    // before the sequence can continue. Flagging it keeps authors honest:
    // sequences must not share their first chord with a single binding.
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Ctrl+K"] }),
      cmd({ id: "b.two", shortcuts: ["Ctrl+K Ctrl+C"] }),
    ]);
    // Distinct normalized keys — no conflict between the *sequences*, the
    // dispatcher resolves "Ctrl+K" as a full match before any second chord.
    expect(registry.detectConflicts()).toEqual([]);
  });

  it("createCommandRegistry throws when definitions contain a conflict", () => {
    expect(() =>
      createCommandRegistry([
        cmd({ id: "a.one", shortcuts: ["Ctrl+X"] }),
        cmd({ id: "b.two", shortcuts: ["Ctrl+X"] }),
      ]),
    ).toThrow(/conflict/i);
  });

  it("register() rejects a duplicate command id", () => {
    const registry = new CommandRegistry([cmd({ id: "a.one" })]);
    expect(() => registry.register(cmd({ id: "a.one" }))).toThrow(
      /duplicate/i,
    );
  });
});

describe("invoke", () => {
  const registry = createCommandRegistry();

  it("runs an enabled command", () => {
    const ctx = mockContext();
    expect(registry.invoke("file.openAudio", ctx, SNAPSHOT_EMPTY)).toBe(true);
    expect(ctx.calls).toEqual(["openAudio"]);
  });

  it("refuses a disabled command — non-executable from any surface", () => {
    const ctx = mockContext();
    // 採譜 needs audio; EMPTY state has none.
    expect(registry.invoke("score.transcribe", ctx, SNAPSHOT_EMPTY)).toBe(
      false,
    );
    expect(ctx.transcribe).not.toHaveBeenCalled();
  });

  it("returns false for unknown ids", () => {
    const ctx = mockContext();
    expect(registry.invoke("no.such", ctx, SNAPSHOT_EMPTY)).toBe(false);
  });

  it("enables transport/edit/export once a score exists", () => {
    const ctx = mockContext();
    for (const [id, spy] of [
      ["transport.toggleLoop", "toggleLoop"],
      ["edit.undo", "undo"],
      ["export.open", "openExport"],
      ["review.next", null], // needs reviewOpen — stays disabled
    ] as const) {
      const ran = registry.invoke(id, ctx, SNAPSHOT_SCORE);
      if (spy) {
        expect(ran).toBe(true);
        expect(ctx.calls).toContain(spy);
      } else {
        expect(ran).toBe(false);
      }
    }
  });
});

describe("visibility", () => {
  const registry = createCommandRegistry();

  it("review commands stay off surfaces until a review exists", () => {
    const visibleEmpty = registry
      .listVisible(SNAPSHOT_EMPTY)
      .map((c) => c.id);
    expect(visibleEmpty).not.toContain("review.open");
    expect(visibleEmpty).not.toContain("review.next");

    const reviewing: CommandSnapshot = {
      ...SNAPSHOT_SCORE,
      reviewOpen: true,
    };
    const visibleReview = registry
      .listVisible(reviewing)
      .map((c) => c.id);
    expect(visibleReview).toContain("review.open");
    expect(visibleReview).toContain("review.next");
    expect(visibleReview).toContain("review.previous");
  });
});

/**
 * Command registry (docs/GUI_UX_SPEC.md §23) — the single source of truth
 * for every invocable action in the app.
 *
 * - Command bar buttons, menus, a future command palette and the keyboard
 *   dispatcher all go through this registry; components never own ad-hoc
 *   keydown handlers for app commands.
 * - Commands are stateless definitions; `isEnabled`/`isVisible` predicates
 *   evaluate against an immutable CommandSnapshot the app rebuilds per
 *   render, so enabled state is always consistent across every surface.
 * - `detectConflicts` catches duplicate bindings at construction time —
 *   see registry.test.ts which asserts the shipped set is conflict-free.
 */

import { parseShortcut, sequenceKey, type KeySequence } from "../keyboard/keys";
import { createCommandDefinitions } from "./definitions";
import type { Command, CommandContext, CommandSnapshot } from "./types";

export type { Command, CommandContext, CommandSnapshot } from "./types";

/** One registered binding: which command owns a parsed sequence. */
export interface CommandBinding {
  readonly command: Command;
  /** The original shortcut string ("Ctrl+Shift+Z"). */
  readonly shortcut: string;
  /** Parsed chord sequence (single chord for all current bindings). */
  readonly sequence: KeySequence;
}

/** A detected shortcut collision between two commands. */
export interface ShortcutConflict {
  readonly shortcut: string;
  readonly commandIds: readonly string[];
}

export class CommandRegistry {
  private readonly byId = new Map<string, Command>();
  private readonly bindingList: CommandBinding[] = [];

  constructor(commands: readonly Command[] = []) {
    for (const command of commands) this.register(command);
  }

  /**
   * Registers a command. Throws on duplicate id — a second registration for
   * an id is always a bug (use a new id or unregister first).
   */
  register(command: Command): void {
    if (this.byId.has(command.id)) {
      throw new Error(`Duplicate command id: "${command.id}"`);
    }
    this.byId.set(command.id, command);
    for (const shortcut of command.shortcuts ?? []) {
      this.bindingList.push({
        command,
        shortcut,
        sequence: parseShortcut(shortcut),
      });
    }
  }

  unregister(id: string): boolean {
    if (!this.byId.delete(id)) return false;
    for (let i = this.bindingList.length - 1; i >= 0; i--) {
      if (this.bindingList[i].command.id === id) this.bindingList.splice(i, 1);
    }
    return true;
  }

  get(id: string): Command | undefined {
    return this.byId.get(id);
  }

  /** All registered commands in registration order. */
  list(): readonly Command[] {
    return [...this.byId.values()];
  }

  /** Commands currently listed on command surfaces (menus/palette). */
  listVisible(snapshot: CommandSnapshot): readonly Command[] {
    return this.list().filter((c) => c.isVisible?.(snapshot) ?? true);
  }

  isEnabled(id: string, snapshot: CommandSnapshot): boolean {
    const command = this.byId.get(id);
    if (!command) return false;
    return command.isEnabled?.(snapshot) ?? true;
  }

  isVisible(id: string, snapshot: CommandSnapshot): boolean {
    const command = this.byId.get(id);
    if (!command) return false;
    return command.isVisible?.(snapshot) ?? true;
  }

  /** Canonical display shortcut (first binding), e.g. "Ctrl+O". */
  shortcutLabel(id: string): string | undefined {
    return this.byId.get(id)?.shortcuts?.[0];
  }

  /**
   * All parsed bindings — consumed by the keyboard dispatcher and by
   * conflict detection. Same normalized sequence under two commands with
   * overlapping scopes is a conflict.
   */
  bindings(): readonly CommandBinding[] {
    return this.bindingList;
  }

  /**
   * Invoke a command by id — the path used by buttons, menus and palette
   * items. Returns false (running nothing) when the command is unknown or
   * disabled, so a disabled command is non-executable from every surface.
   */
  invoke(
    id: string,
    ctx: CommandContext,
    snapshot: CommandSnapshot,
  ): boolean {
    const command = this.byId.get(id);
    if (!command) return false;
    if (!(command.isEnabled?.(snapshot) ?? true)) return false;
    command.run(ctx, snapshot);
    return true;
  }

  /**
   * Finds duplicate normalized bindings. Two commands binding the same
   * chord sequence is always a conflict — all commands share the workspace
   * scope, so overlapping `isEnabled` predicates cannot rescue it.
   */
  detectConflicts(): ShortcutConflict[] {
    const bySequence = new Map<string, Set<string>>();
    for (const binding of this.bindingList) {
      const key = sequenceKey(binding.sequence);
      const ids = bySequence.get(key) ?? new Set<string>();
      ids.add(binding.command.id);
      bySequence.set(key, ids);
    }
    const conflicts: ShortcutConflict[] = [];
    for (const [shortcut, ids] of bySequence) {
      if (ids.size > 1) {
        conflicts.push({ shortcut, commandIds: [...ids] });
      }
    }
    return conflicts;
  }
}

/**
 * Render-scoped view of the registry for components. Bound to one snapshot
 * so every surface (command bar, transport, menus) agrees on enabled state
 * within a render; `invoke` routes through the same predicates as keyboard
 * dispatch, so a disabled command is non-executable everywhere.
 */
export interface CommandSurface {
  /** Runs the command when enabled; returns whether it ran. */
  invoke(id: string): boolean;
  isEnabled(id: string): boolean;
  isVisible(id: string): boolean;
  /** Japanese title for buttons/menus ("" when the id is unknown). */
  title(id: string): string;
  /** Canonical display shortcut, e.g. "Ctrl+O". */
  shortcutLabel(id: string): string | undefined;
}

export function createCommandSurface(
  registry: CommandRegistry,
  ctx: CommandContext,
  snapshot: CommandSnapshot,
): CommandSurface {
  return {
    invoke: (id) => registry.invoke(id, ctx, snapshot),
    isEnabled: (id) => registry.isEnabled(id, snapshot),
    isVisible: (id) => registry.isVisible(id, snapshot),
    title: (id) => registry.get(id)?.title ?? "",
    shortcutLabel: (id) => registry.shortcutLabel(id),
  };
}

/**
 * Builds the app registry from the built-in definitions and fails fast on
 * shortcut conflicts — a conflicting registration must never ship silently.
 */
export function createCommandRegistry(
  commands: readonly Command[] = createCommandDefinitions(),
): CommandRegistry {
  const registry = new CommandRegistry(commands);
  const conflicts = registry.detectConflicts();
  if (conflicts.length > 0) {
    const detail = conflicts
      .map((c) => `${c.shortcut}: ${c.commandIds.join(", ")}`)
      .join("; ");
    throw new Error(`Shortcut conflicts in command registry: ${detail}`);
  }
  return registry;
}

/**
 * Command model types (docs/GUI_UX_SPEC.md §23).
 *
 * A Command is a *stateless* description: predicates receive a
 * CommandSnapshot so the same definitions can be evaluated for menus,
 * keyboard dispatch, palette listing and tests without re-registering.
 */

/** Pitch display modes (GUI_UX_SPEC §7). Kept literal here so the command
 *  layer does not depend on a component file. */
export type PitchViewSetting = "concert" | "hornF";

/** Top-level screens that gate command availability. */
export type AppView = "workspace" | "settings";

/** Grouping for menus / command palette / docs. */
export type CommandSection =
  | "file"
  | "score"
  | "transport"
  | "view"
  | "review"
  | "edit"
  | "export"
  | "nav"
  | "app";

/**
 * Immutable read of the app state that command predicates evaluate.
 * The app builds one per render; the registry never stores it.
 */
export interface CommandSnapshot {
  /** A source audio file is loaded (GUI_UX_SPEC §4, AUDIO_READY+). */
  readonly hasAudio: boolean;
  /** A canonical score exists (SCORE_READY+). */
  readonly hasScore: boolean;
  /** Transcription is running — score-writing commands disable (§5). */
  readonly isTranscribing: boolean;
  /** Audio is currently playing (drives the play/pause affordance). */
  readonly isPlaying: boolean;
  /** Loop range playback is armed. */
  readonly loopEnabled: boolean;
  /** Current pitch display mode. */
  readonly pitch: PitchViewSetting;
  /** Undo/redo stacks (§14 — all edits are commands). */
  readonly canUndo: boolean;
  readonly canRedo: boolean;
  /** A note/region is selected (gates Esc = clear selection). */
  readonly hasSelection: boolean;
  /** 要確認 workspace state. */
  readonly reviewOpen: boolean;
  readonly reviewCount: number;
  /** Active top-level view. */
  readonly view: AppView;
}

/**
 * The services commands act on. The app supplies implementations; during
 * the spike most are stubs that announce via `announce` so every invocation
 * produces honest feedback in the (aria-live) status bar.
 */
export interface CommandContext {
  openAudio(): void;
  transcribe(): void;
  togglePlayPause(): void;
  stop(): void;
  jumpBack(): void;
  jumpForward(): void;
  seekToStart(): void;
  seekToEnd(): void;
  toggleLoop(): void;
  setPitchView(view: PitchViewSetting): void;
  openReview(): void;
  reviewNext(): void;
  reviewPrevious(): void;
  undo(): void;
  redo(): void;
  openExport(): void;
  zoomScoreIn(): void;
  zoomScoreOut(): void;
  zoomScoreFit(): void;
  clearSelection(): void;
  openSettings(): void;
  /** F6 region navigation — implemented by focus/zones. */
  focusNextRegion(): void;
  focusPreviousRegion(): void;
  /**
   * Surface command feedback in the status area (role="status" is
   * aria-live, so Narrator users hear the result — UX_VALIDATION §11).
   */
  announce(message: string): void;
}

/**
 * A single invocable command — the unit the registry, command bar, menus,
 * palette and keyboard dispatcher all share (single source of truth).
 */
export interface Command {
  /** Stable dotted id, e.g. "transport.playPause". */
  readonly id: string;
  /**
   * Japanese title — the only UI language (UI_COPY_CONTRACT). This is what
   * buttons, menus, a palette and screen readers all announce.
   */
  readonly title: string;
  /** Optional longer Japanese description for palettes/menus. */
  readonly description?: string;
  readonly section: CommandSection;
  /**
   * Keyboard bindings in "Ctrl+Shift+Z" notation; whitespace separates
   * chords in a multi-step sequence. The first entry is the canonical
   * binding shown in tooltips / aria-keyshortcuts.
   */
  readonly shortcuts?: readonly string[];
  /**
   * May run against this snapshot. Default: enabled. Disabled commands are
   * non-executable everywhere — toolbar, menu AND shortcut (issue req:
   * "disabled commands remain non-executable via shortcut").
   */
  readonly isEnabled?: (snapshot: CommandSnapshot) => boolean;
  /**
   * Listed on command surfaces (palette/menus/overflow). Default: visible.
   * Hidden commands still run when enabled — e.g. 採譜し直す vs 採譜.
   */
  readonly isVisible?: (snapshot: CommandSnapshot) => boolean;
  /** May fire while a text field / IME host has focus. Default false. */
  readonly allowInTextInput?: boolean;
  /** May fire while a modal dialog/sheet owns focus. Default false. */
  readonly allowInModal?: boolean;
  /** Re-fires on key auto-repeat. Default false (no accidental toggles). */
  readonly allowRepeat?: boolean;
  /** Execute against live services. */
  readonly run: (ctx: CommandContext, snapshot: CommandSnapshot) => void;
}

