/**
 * @vitest-environment jsdom
 *
 * Focus restoration tests (issue UI-012: "dialog close restores opener
 * focus", "focus restoration tests exist").
 */

import { afterEach, describe, expect, it } from "vitest";
import { createFocusRestorer } from "./focusRestore";

function button(label = "opener"): HTMLButtonElement {
  const el = document.createElement("button");
  el.type = "button";
  el.textContent = label;
  document.body.appendChild(el);
  return el;
}

afterEach(() => {
  document.body.innerHTML = "";
});

describe("createFocusRestorer", () => {
  it("restores focus to the opener when focus stranded on <body>", () => {
    const opener = button();
    opener.focus();
    const restorer = createFocusRestorer(document);
    restorer.capture();

    // Dialog closed, focus dropped to body — the stranded case.
    (document.activeElement as HTMLElement).blur?.();
    expect(document.activeElement).toBe(document.body);

    expect(restorer.restore()).toBe(true);
    expect(document.activeElement).toBe(opener);
    opener.remove();
  });

  it("does not steal focus when the user moved somewhere real", () => {
    const opener = button();
    const other = button("other");
    opener.focus();
    const restorer = createFocusRestorer(document);
    restorer.capture();

    // User deliberately moved focus — restoration must not override it.
    other.focus();
    expect(restorer.restore()).toBe(false);
    expect(document.activeElement).toBe(other);
  });

  it("returns false when the opener is gone from the DOM", () => {
    const opener = button();
    opener.focus();
    const restorer = createFocusRestorer(document);
    restorer.capture();
    opener.remove(); // opener unmounted while the surface was open
    (document.activeElement as HTMLElement | null)?.blur?.();

    expect(restorer.restore()).toBe(false);
  });

  it("force mode restores even when focus is elsewhere", () => {
    const opener = button();
    const other = button("other");
    opener.focus();
    const restorer = createFocusRestorer(document);
    restorer.capture();
    other.focus();

    expect(restorer.restore({ force: true })).toBe(true);
    expect(document.activeElement).toBe(opener);
  });

  it("capture ignores <body> — there is nothing meaningful to restore to", () => {
    const restorer = createFocusRestorer(document);
    restorer.capture();
    expect(restorer.captured).toBeNull();
    expect(restorer.restore()).toBe(false);
  });

  it("restore is idempotent after success", () => {
    const opener = button();
    opener.focus();
    const restorer = createFocusRestorer(document);
    restorer.capture();
    (document.activeElement as HTMLElement).blur?.();
    expect(restorer.restore()).toBe(true);
    expect(restorer.restore()).toBe(false); // already consumed
  });
});

/**
 * Focus restoration (GUI_UX_SPEC §22, issue UI-012).
 *
 * "dialog close restores opener focus" — the restorer captures the element
 * that had focus when a surface opened and gives focus back when it closes.
 * Restoration only fires when focus is stranded (active element is the body
 * or a detached node), so it never yanks focus away from somewhere the user
 * deliberately moved it, and never fights Fluent's own trigger-restore.
 *
 * `createFocusRestorer` takes a Document so tests can run it against jsdom
 * without globals; the React hook wires it to surface open state.
 */

export interface FocusRestorer {
  /** Remembers the element that holds focus right now. */
  capture(): void;
  /**
   * Focuses the captured element when focus is currently stranded
   * (document.body / detached node). Returns true when focus moved.
   * `force` skips the stranded check — used by tests and explicit flows.
   */
  restore(options?: { force?: boolean }): boolean;
  /** Drops the saved reference without restoring. */
  clear(): void;
  /** The captured element (mostly for tests/diagnostics). */
  readonly captured: Element | null;
}

function isFocusable(el: Element): el is HTMLElement {
  return typeof (el as HTMLElement).focus === "function";
}

export function createFocusRestorer(doc: Document = document): FocusRestorer {
  let saved: Element | null = null;
  return {
    capture() {
      const active = doc.activeElement;
      // Never capture <body> itself — restoring "to body" is meaningless.
      saved = active && active !== doc.body ? active : null;
    },
    restore({ force = false } = {}) {
      if (!saved || !isFocusable(saved)) return false;
      if (!saved.isConnected) {
        // Opener is gone — nothing sensible to return focus to.
        saved = null;
        return false;
      }
      const active = doc.activeElement;
      const stranded =
        force ||
        active == null ||
        active === doc.body ||
        !active.isConnected;
      if (!stranded) {
        // Focus already lives somewhere real — don't steal it back.
        saved = null;
        return false;
      }
      const target = saved;
      saved = null;
      target.focus();
      return doc.activeElement === target;
    },
    clear() {
      saved = null;
    },
    get captured() {
      return saved;
    },
  };
}

/**
 * useFocusRestoreOnClose — wires FocusRestorer to a surface's open state
 * (GUI_UX_SPEC §22: "dialog close restores opener focus").
 *
 * Usage: call with the same `open` value passed to HsDialog / HsSheet /
 * HsPopover. On open the focused element is captured; on close (or unmount
 * while open) focus returns to it — but only if focus would otherwise be
 * stranded on <body>, so deliberate focus moves are never overridden and
 * Fluent's own trigger-restore keeps precedence.
 */

import { useEffect } from "react";
import { createFocusRestorer } from "./focusRestore";

export function useFocusRestoreOnClose(open: boolean): void {
  useEffect(() => {
    if (!open) return;
    const restorer = createFocusRestorer();
    restorer.capture();
    return () => {
      // The closing surface has just unmounted (cleanup runs after the
      // commit). If it had exit animation that kept it mounted, a deferred
      // pass catches the eventual stranded focus too — the second call is
      // a no-op once the first restored (or intentionally skipped).
      restorer.restore();
      window.setTimeout(() => restorer.restore(), 0);
    };
  }, [open]);
}

