/**
 * Central keyboard dispatcher (docs/GUI_UX_SPEC.md §9, §22, §23).
 *
 * One dispatcher per app; a single `keydown` listener at the window level
 * feeds it. Components do not register their own command shortcuts.
 *
 * Guarantees:
 * - IME safety: events during composition (`isComposing`, keyCode 229) are
 *   ignored, so Japanese input never triggers commands.
 * - Text-entry safety: inside text fields only commands that opt in via
 *   `allowInTextInput` are considered (J/K/L stay disabled while typing).
 * - Control cooperation: keys a focused control owns (Space on a button,
 *   arrows on a slider, typeahead on a select) are left to the control.
 * - Modal safety: while a dialog/drawer owns focus, only `allowInModal`
 *   commands are considered.
 * - Disabled commands are still swallowed (the event is consumed but the
 *   command does not run) so a known-but-disabled shortcut is inert rather
 *   than falling through to browser defaults like Ctrl+O.
 * - Chord sequences: multi-chord bindings ("Ctrl+K Ctrl+C") hold a pending
 *   prefix for `sequenceTimeoutMs`.
 */

import {
  chordFromEvent,
  isSequencePrefix,
  type KeyChord,
  type KeyEventLike,
} from "./keys";
import {
  controlConsumesChord,
  isModalTarget,
  isTextEntryTarget,
} from "./targets";
import type {
  Command,
  CommandContext,
  CommandSnapshot,
} from "../commands/types";
import type { CommandRegistry } from "../commands/registry";

export type DispatchKind =
  /** Event ran a command. */
  | "ran"
  /** Known shortcut, command currently disabled — consumed, not run. */
  | "disabled"
  /** Event extends a pending multi-chord sequence — consumed. */
  | "sequence-pending"
  /** Key auto-repeat for a non-repeatable command — consumed, not run. */
  | "repeat"
  /** Suppressed by scope (IME / text input / modal / owning control). */
  | "suppressed"
  /** No binding matched. */
  | "unmatched";

export interface DispatchResult {
  readonly kind: DispatchKind;
  readonly commandId?: string;
  /** Whether the host should call preventDefault() on the event. */
  readonly shouldPreventDefault: boolean;
}

export interface KeyboardDispatcherOptions {
  readonly registry: CommandRegistry;
  /** Latest app-state snapshot — read lazily per event. */
  readonly getSnapshot: () => CommandSnapshot;
  /** Live services commands act on. */
  readonly context: CommandContext;
  /** Pending multi-chord sequence timeout (default 1000ms). */
  readonly sequenceTimeoutMs?: number;
  /** Clock injection for tests (default Date.now). */
  readonly now?: () => number;
}

interface PendingSequence {
  chords: KeyChord[];
  at: number;
}

const RAN: DispatchResult = { kind: "ran", shouldPreventDefault: true };
const IGNORED: DispatchResult = { kind: "suppressed", shouldPreventDefault: false };
const UNMATCHED: DispatchResult = { kind: "unmatched", shouldPreventDefault: false };

export class KeyboardDispatcher {
  private readonly options: KeyboardDispatcherOptions;
  private pending: PendingSequence | null = null;

  constructor(options: KeyboardDispatcherOptions) {
    this.options = options;
  }

  /** Drops any pending multi-chord prefix (e.g. on blur). */
  resetPending(): void {
    this.pending = null;
  }

  /**
   * Handles one keydown event. The caller preventDefaults when
   * `result.shouldPreventDefault` is true.
   */
  handleKeyDown(e: KeyEventLike): DispatchResult {
    // 1. IME composition in progress — never dispatch (UI_COPY_CONTRACT).
    if (e.isComposing || e.keyCode === 229) return IGNORED;

    const chord = chordFromEvent(e);

    // 2. Scope resolution: modal > text-entry > workspace.
    const inModal = isModalTarget(e.target ?? null);
    const inTextInput = !inModal && isTextEntryTarget(e.target ?? null);

    // 3. Chords the focused control owns are left alone (Space on a button
    //    etc.). Ctrl/Alt chords are never consumed by native controls.
    if (
      !inModal &&
      !inTextInput &&
      controlConsumesChord(e.target ?? null, chord)
    ) {
      return IGNORED;
    }

    // 4. Candidate bindings filtered by scope.
    const eligible = this.options.registry.bindings().filter(({ command }) => {
      if (inModal) return command.allowInModal === true;
      if (inTextInput) return command.allowInTextInput === true;
      return true;
    });

    const now = (this.options.now ?? Date.now)();
    const timeoutMs = this.options.sequenceTimeoutMs ?? 1000;
    if (this.pending && now - this.pending.at > timeoutMs) {
      this.pending = null; // stale prefix expired
    }

    // Matches `events` against eligible bindings: a "full" match runs, a
    // "partial" one means the events are a strict prefix of a longer
    // sequence and should be held as pending.
    const tryMatch = (
      events: readonly KeyChord[],
    ): { type: "full"; command: Command } | { type: "partial" } | null => {
      for (const { command, sequence } of eligible) {
        if (
          sequence.length === events.length &&
          isSequencePrefix(events, sequence)
        ) {
          return { type: "full", command };
        }
      }
      for (const { sequence } of eligible) {
        if (
          sequence.length > events.length &&
          isSequencePrefix(events, sequence)
        ) {
          return { type: "partial" };
        }
      }
      return null;
    };

    const hadPending = this.pending !== null;
    const match = tryMatch([...(this.pending?.chords ?? []), chord]);
    if (match?.type === "full") {
      this.pending = null;
      return this.activate(match.command, e);
    }
    if (match?.type === "partial") {
      this.pending = {
        chords: [...(this.pending?.chords ?? []), chord],
        at: now,
      };
      return { kind: "sequence-pending", shouldPreventDefault: true };
    }

    // Dead sequence (or none): retry this event on its own — it may still
    // complete a single-chord binding or open a fresh sequence prefix.
    this.pending = null;
    if (hadPending) {
      const retry = tryMatch([chord]);
      if (retry?.type === "full") return this.activate(retry.command, e);
      if (retry?.type === "partial") {
        this.pending = { chords: [chord], at: now };
        return { kind: "sequence-pending", shouldPreventDefault: true };
      }
    }
    // Scope-restricted events that matched nothing were actively suppressed
    // (the binding may exist but is not eligible here); outside restricted
    // scopes a miss is simply an unbound key.
    return inModal || inTextInput ? IGNORED : UNMATCHED;
  }

  private activate(command: Command, e: KeyEventLike): DispatchResult {
    // Held-key auto-repeat only re-runs commands that opt in.
    if (e.repeat === true && command.allowRepeat !== true) {
      return {
        kind: "repeat",
        commandId: command.id,
        shouldPreventDefault: true,
      };
    }
    const snapshot = this.options.getSnapshot();
    if (!(command.isEnabled?.(snapshot) ?? true)) {
      // Known shortcut, currently disabled: consume the event so the
      // binding is inert rather than leaking to the browser (issue req:
      // "disabled commands remain non-executable via shortcut").
      return {
        kind: "disabled",
        commandId: command.id,
        shouldPreventDefault: true,
      };
    }
    command.run(this.options.context, snapshot);
    return { ...RAN, commandId: command.id };
  }
}

/**
 * Keyboard chord model (docs/GUI_UX_SPEC.md §23).
 *
 * A `KeyChord` is one physical key press plus its modifiers ("Ctrl+Shift+Z",
 * "F6", "Space"). A `KeySequence` is an ordered list of chords so the
 * registry can express multi-step bindings ("Ctrl+K Ctrl+C") even though the
 * initial shortcut table only uses single chords.
 *
 * This module is pure: it has no DOM, React, or command-registry dependency
 * so it can be unit-tested in isolation and reused by any dispatcher.
 */

/**
 * Minimal structural view of a keyboard event. `KeyboardEvent` satisfies
 * this interface, and tests can build plain objects without a DOM.
 */
export interface KeyEventLike {
  readonly key: string;
  readonly ctrlKey: boolean;
  readonly shiftKey: boolean;
  readonly altKey: boolean;
  readonly metaKey?: boolean;
  /** True while an IME composition is in progress (`keydown` only). */
  readonly isComposing?: boolean;
  /** Legacy but still the reliable IME sentinel: 229 during composition. */
  readonly keyCode?: number;
  readonly repeat?: boolean;
  readonly target?: EventTarget | null;
}

export interface KeyChord {
  readonly ctrl: boolean;
  readonly shift: boolean;
  readonly alt: boolean;
  /** Normalized key name: lowercase, "space" for " ". See normalizeKey. */
  readonly key: string;
}

/** An ordered chord sequence; a single chord is the common case. */
export type KeySequence = readonly KeyChord[];

/**
 * Characters whose glyph already encodes Shift on US/JIS layouts. When the
 * event key is one of these, a binding that spells the glyph directly
 * ("Ctrl++") must not require the shift flags to be equal — pressing "+"
 * physically requires Shift, so `Ctrl+Shift+=` arrives as Ctrl+Shift+"+".
 */
const SHIFT_IMPLICIT_KEYS = new Set([
  "+",
  "_",
  "!",
  "@",
  "#",
  "$",
  "%",
  "^",
  "&",
  "*",
  "(",
  ")",
  "{",
  "}",
  "|",
  ":",
  '"',
  "<",
  ">",
  "?",
  "~",
]);

/**
 * Normalizes `KeyboardEvent.key` / shortcut string key parts into the
 * canonical form used inside KeyChord. Single characters lowercase;
 * whitespace variants collapse to "space".
 */
export function normalizeKey(key: string): string {
  const trimmed = key.trim();
  if (trimmed === "") return "space"; // KeyboardEvent.key === " "
  const lower = trimmed.toLowerCase();
  switch (lower) {
    case "spacebar": // pre-standard name
    case "space":
      return "space";
    case "esc":
      return "escape";
    case "del":
      return "delete";
    case "return":
      return "enter";
    case "arrowup":
    case "arrowdown":
    case "arrowleft":
    case "arrowright":
      return lower;
    default:
      return lower;
  }
}

/** Display name for a normalized key ("space"→"Space", "f6"→"F6"). */
export function displayKey(key: string): string {
  if (key === "space") return "Space";
  if (key === "escape") return "Esc";
  if (key.length === 1) return key.toUpperCase();
  // "arrowleft" → "ArrowLeft", "f6" → "F6", "pageup" → "PageUp"
  const special: Record<string, string> = {
    arrowup: "ArrowUp",
    arrowdown: "ArrowDown",
    arrowleft: "ArrowLeft",
    arrowright: "ArrowRight",
    pageup: "PageUp",
    pagedown: "PageDown",
    home: "Home",
    end: "End",
    delete: "Delete",
    backspace: "Backspace",
    enter: "Enter",
    tab: "Tab",
    insert: "Insert",
  };
  return special[key] ?? key.charAt(0).toUpperCase() + key.slice(1);
}

const MODIFIERS: Record<string, "ctrl" | "shift" | "alt" | "meta"> = {
  ctrl: "ctrl",
  control: "ctrl",
  shift: "shift",
  alt: "alt",
  option: "alt",
  meta: "meta",
  cmd: "meta",
  win: "meta",
};

/**
 * Parses one chord string like "Ctrl+Shift+Z", "F6" or "Space".
 * The key is the last "+"-separated part; a trailing "+" means the key
 * itself is "+" (so "Ctrl++" parses as Ctrl + "+").
 *
 * HornScribe is Windows-first; Meta is parsed for completeness but no
 * built-in binding uses it.
 */
export function parseChord(text: string): KeyChord {
  const parts = text.trim().split("+");
  let keyPart = parts.pop() ?? "";
  if (keyPart === "" && parts.length > 0) {
    // Trailing "+": the key is literally "+".
    keyPart = "+";
    parts.pop(); // drop the empty segment left behind
  }
  if (keyPart === "" || parts.some((p) => p.trim() === "")) {
    throw new Error(`Invalid chord: "${text}"`);
  }
  if (MODIFIERS[keyPart.trim().toLowerCase()] !== undefined) {
    throw new Error(`Chord "${text}" has a modifier as its key`);
  }
  let ctrl = false;
  let shift = false;
  let alt = false;
  for (const part of parts) {
    const mod = MODIFIERS[part.trim().toLowerCase()];
    if (!mod) {
      throw new Error(`Invalid modifier "${part}" in chord "${text}"`);
    }
    if (mod === "ctrl") ctrl = true;
    else if (mod === "shift") shift = true;
    else if (mod === "alt") alt = true;
    // meta is accepted but unused by built-in bindings (Windows-first app)
  }
  return { ctrl, shift, alt, key: normalizeKey(keyPart) };
}

/**
 * Parses a full shortcut string into a chord sequence. Chords are separated
 * by whitespace, so the space bar must be spelled "Space" ("Ctrl+Space",
 * never a literal " " inside a sequence).
 */
export function parseShortcut(text: string): KeySequence {
  const chords = text
    .trim()
    .split(/\s+/)
    .map(parseChord);
  if (chords.length === 0) throw new Error(`Invalid shortcut: "${text}"`);
  return chords;
}

/** Builds the chord a physical key event represents. */
export function chordFromEvent(e: KeyEventLike): KeyChord {
  return {
    ctrl: e.ctrlKey,
    shift: e.shiftKey,
    alt: e.altKey,
    key: normalizeKey(e.key),
  };
}

/**
 * True when a physical chord event satisfies a bound chord.
 * Modifier equality is strict except for shift on SHIFT_IMPLICIT_KEYS —
 * "+" can only be produced with Shift held, so "Ctrl++" must match the
 * real Ctrl+Shift+"+" event (GUI_UX_SPEC §15 zoom keys).
 */
export function chordSatisfiedBy(chord: KeyChord, event: KeyChord): boolean {
  if (chord.key !== event.key) return false;
  if (chord.ctrl !== event.ctrl) return false;
  if (chord.alt !== event.alt) return false;
  if (chord.shift === event.shift) return true;
  return SHIFT_IMPLICIT_KEYS.has(chord.key);
}

export function chordsEqual(a: KeyChord, b: KeyChord): boolean {
  return (
    a.key === b.key && a.ctrl === b.ctrl && a.shift === b.shift && a.alt === b.alt
  );
}

/** Canonical "Ctrl+Shift+Z" rendering of a chord (for UI + conflict keys). */
export function formatChord(chord: KeyChord): string {
  const parts: string[] = [];
  if (chord.ctrl) parts.push("Ctrl");
  if (chord.shift) parts.push("Shift");
  if (chord.alt) parts.push("Alt");
  parts.push(displayKey(chord.key));
  return parts.join("+");
}

/** Canonical rendering of a sequence: chords joined by a single space. */
export function formatSequence(sequence: KeySequence): string {
  return sequence.map(formatChord).join(" ");
}

/**
 * Stable string key for a sequence — used by conflict detection so that
 * "Ctrl+shift+z" and "Ctrl+Shift+Z" are recognized as the same binding.
 */
export function sequenceKey(sequence: KeySequence): string {
  return formatSequence(sequence);
}

/**
 * True when the pressed `events` satisfy a leading prefix of the bound
 * `sequence` (or the whole sequence when lengths are equal). Uses
 * chordSatisfiedBy so shift-implicit symbols ("+") match correctly.
 */
export function isSequencePrefix(
  events: readonly KeyChord[],
  sequence: KeySequence,
): boolean {
  if (events.length > sequence.length) return false;
  return events.every((event, i) => chordSatisfiedBy(sequence[i], event));
}

/**
 * Keyboard target classification (docs/GUI_UX_SPEC.md §9, §22, §23).
 *
 * Decides, for a given event target, which commands are eligible:
 * - text-entry targets (input/textarea/contenteditable) suppress shortcuts —
 *   Japanese IME composition and plain typing must never trigger commands;
 * - modal surfaces (dialog / alertdialog / drawer) suppress everything —
 *   the surface owns the keyboard until it closes;
 * - interactive controls "consume" the keys their role needs (a focused
 *   button owns Space/Enter; a slider owns arrows/Home/End), so global
 *   single-key commands don't fight built-in control behavior.
 *
 * All predicates take `EventTarget | null` and degrade to "not scoped"
 * for non-element targets so the dispatcher is testable with stubs.
 */

import type { KeyChord } from "./keys";

function asElement(target: EventTarget | null): Element | null {
  if (target instanceof Element) return target;
  // Support event targets like window/document — never scoped.
  if (target instanceof Document) return target.documentElement;
  return null;
}

/** INPUT types that accept free text (IME-relevant). */
const TEXT_INPUT_TYPES = new Set([
  "", // default type
  "text",
  "search",
  "url",
  "tel",
  "password",
  "email",
  "number",
]);

/**
 * True when the event originates in a free-text editing context where all
 * app shortcuts are suppressed unless the command opts in via
 * `allowInTextInput` (MASTER_PLAN §8 / UI_COPY_CONTRACT IME requirement).
 */
export function isTextEntryTarget(target: EventTarget | null): boolean {
  const el = asElement(target);
  if (!(el instanceof HTMLElement)) return false;
  if (el.isContentEditable) return true;
  if (el.tagName === "TEXTAREA") return true;
  if (el.tagName === "INPUT") {
    const type = (el.getAttribute("type") ?? "").toLowerCase();
    return TEXT_INPUT_TYPES.has(type);
  }
  // Editing hosts nested inside a text field (e.g. a clear button rendered
  // inside an input wrapper is still an editing context for our purposes —
  // the closest() check keeps events from inner decoration scoped).
  return el.closest("input, textarea, [contenteditable='true']") !== null;
}

/**
 * True when the event originates inside a modal surface that owns focus
 * (Fluent Dialog/alertdialog, OverlayDrawer which renders role="dialog",
 * or any element explicitly marked `data-hs-modal`). Commands are
 * suppressed unless they set `allowInModal` — Escape/Tab/Enter are left to
 * the surface itself.
 */
export function isModalTarget(target: EventTarget | null): boolean {
  const el = asElement(target);
  if (!el) return false;
  return (
    el.closest('[role="dialog"], [role="alertdialog"], [data-hs-modal]') !==
    null
  );
}

/**
 * Keys consumed by the interactive control under the target, so the
 * dispatcher can leave them alone. Roles/tags are matched via closest() so
 * inner markup (icons inside a button) still resolves to its control.
 */
const CONTROL_SELECTOR = [
  "button",
  "a[href]",
  "select",
  "summary",
  "input",
  '[role="button"]',
  '[role="link"]',
  '[role="menuitem"]',
  '[role="menuitemcheckbox"]',
  '[role="menuitemradio"]',
  '[role="checkbox"]',
  '[role="radio"]',
  '[role="switch"]',
  '[role="tab"]',
  '[role="option"]',
  '[role="treeitem"]',
  '[role="slider"]',
  '[role="spinbutton"]',
  '[role="scrollbar"]',
  '[role="combobox"]',
  '[role="listbox"]',
  '[role="menu"]',
  '[role="listbox"]',
].join(", ");

/** Printable-key check: one character (letter/digit/punct) or space. */
function isPrintableChord(chord: KeyChord): boolean {
  if (chord.ctrl || chord.alt) return false;
  return chord.key.length === 1 || chord.key === "space";
}

const NAVIGATION_KEYS = new Set([
  "arrowup",
  "arrowdown",
  "arrowleft",
  "arrowright",
  "home",
  "end",
  "pageup",
  "pagedown",
]);

/**
 * True when the interactive control under `target` owns this chord, so the
 * global dispatcher must not run a command bound to it.
 *
 * Examples: Space on a focused button activates the button (not
 * play/pause); arrows inside a radiogroup move selection; typeahead keys on
 * a select jump to options. Ctrl-modified chords are never consumed by
 * native controls here, so Ctrl-based commands keep working when a control
 * has focus.
 */
export function controlConsumesChord(
  target: EventTarget | null,
  chord: KeyChord,
): boolean {
  const el = asElement(target);
  if (!el) return false;
  const control = el.closest(CONTROL_SELECTOR);
  if (!control) return false;

  const role = control.getAttribute("role");
  const tag = control.tagName.toLowerCase();
  const kind =
    role ??
    (tag === "input"
      ? `input-${(control.getAttribute("type") ?? "text").toLowerCase()}`
      : tag);

  const activation = chord.key === "enter" || chord.key === "space";
  const navigation = NAVIGATION_KEYS.has(chord.key);
  const printable = isPrintableChord(chord);

  switch (kind) {
    // Activatables consume Space/Enter so global Space never fires while a
    // button/menu item/link/tab is focused.
    case "button":
    case "a":
    case "summary":
    case "link":
    case "menuitem":
    case "menuitemcheckbox":
    case "menuitemradio":
    case "option":
    case "treeitem":
    case "tab":
    case "input-button":
    case "input-submit":
    case "input-reset":
    case "input-image":
      return activation && !chord.ctrl && !chord.alt;
    // Toggle controls consume Space only (Enter is not an activator).
    case "checkbox":
    case "radio":
    case "switch":
    case "input-checkbox":
    case "input-radio":
      return chord.key === "space" && !chord.ctrl && !chord.alt;
    // Value widgets own arrow/Home/End/PageUp/PageDown for adjustment.
    case "slider":
    case "spinbutton":
    case "scrollbar":
    case "input-range":
      return navigation && !chord.ctrl && !chord.alt;
    // Pickers consume activation, navigation, typeahead printables, and
    // Escape (closing their popup) so nothing double-handles.
    case "select":
    case "combobox":
    case "listbox":
    case "menu":
      return (
        (activation || navigation || printable || chord.key === "escape") &&
        !chord.ctrl &&
        !chord.alt
      );
    default:
      return activation && !chord.ctrl && !chord.alt;
  }
}

/**
 * React wiring for the KeyboardDispatcher (GUI_UX_SPEC §23).
 *
 * The app installs exactly one window-level keydown listener through this
 * hook — the "no ad-hoc component key handlers" rule is enforced by giving
 * components no reason to have one.
 */

import { useEffect } from "react";
import type { KeyboardDispatcher } from "./dispatcher";

export function useCommandKeyboard(
  dispatcher: KeyboardDispatcher | null,
): void {
  useEffect(() => {
    if (!dispatcher) return;
    const onKeyDown = (e: KeyboardEvent) => {
      const result = dispatcher.handleKeyDown(e);
      if (result.shouldPreventDefault) e.preventDefault();
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [dispatcher]);
}

/**
 * HornScribe app shell layout + token consumers.
 * Colors come only from --hs-* semantic tokens (tokens.css).
 */

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--hs-font-family);
  font-size: var(--hs-font-size-body);
  color: var(--hs-text-primary);
  background: var(--hs-surface-app);
  overflow: hidden;
}

/* ---- Visible keyboard focus (DESIGN_SYSTEM §16) ----
   2px+, distinct from adjacent surface; Fluent v9 components draw their own
   compatible focus ring, this guarantees the same contract for every other
   focusable region (waveform, score surface, segmented control, links). */
:focus-visible {
  outline: var(--hs-focus-width) solid var(--hs-focus);
  outline-offset: var(--hs-focus-offset);
  border-radius: var(--hs-radius-input);
}
/* Never remove the outline without a replacement. */
:focus:not(:focus-visible) {
  outline: none;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* ============================ App shell ============================ */
/* GUI_UX_SPEC §2 information architecture:
   title bar → command bar → waveform → score workspace → transport → status */
.hs-shell {
  display: grid;
  grid-template-rows: auto auto auto minmax(0, 1fr) auto auto;
  grid-template-areas:
    "titlebar"
    "commandbar"
    "waveform"
    "main"
    "transport"
    "statusbar";
  height: 100%;
  min-width: 0;
  background: var(--hs-surface-app);
  color: var(--hs-text-primary);
}

/* ---- Title bar area (in-app; native window chrome is kept) ---- */
.hs-titlebar {
  grid-area: titlebar;
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  height: 32px;
  padding: 0 var(--hs-space-ms);
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-secondary);
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
  user-select: none;
}
.hs-titlebar__app {
  font-weight: 600;
  color: var(--hs-text-primary);
}
.hs-titlebar__doc {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---- Command bar (DESIGN_SYSTEM §10: ~44px, never scrolls) ---- */
.hs-commandbar {
  grid-area: commandbar;
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  height: 44px;
  padding: 0 var(--hs-space-ms);
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
  overflow: hidden;
  white-space: nowrap;
}
.hs-commandbar__spacer {
  flex: 1 1 auto;
  min-width: var(--hs-space-sm);
}

/* ---- Segmented control (DESIGN_SYSTEM §11: text labels, never icon-only) ---- */
.hs-segmented {
  display: inline-flex;
  flex: 0 0 auto;
  border: 1px solid var(--hs-border-strong);
  border-radius: var(--hs-radius-input);
  overflow: hidden;
  background: var(--hs-surface-elevated);
}
.hs-segmented__item {
  appearance: none;
  border: none;
  background: transparent;
  color: var(--hs-text-secondary);
  font-family: var(--hs-font-family);
  font-size: var(--hs-font-size-compact);
  line-height: 1;
  padding: 8px 12px;
  cursor: pointer;
  white-space: nowrap;
}
.hs-segmented__item + .hs-segmented__item {
  border-left: 1px solid var(--hs-border-subtle);
}
.hs-segmented__item:hover {
  background: var(--hs-control-hover);
}
/* selected state = fill + weight + border cues combined (§11);
   on-accent text color keeps ≥4.5:1 in both themes (dark accent is light,
   so the foreground flips to dark ink via --hs-accent-foreground). */
.hs-segmented__item[aria-checked="true"] {
  background: var(--hs-accent);
  color: var(--hs-accent-foreground);
  font-weight: var(--hs-font-weight-emphasis);
  box-shadow: inset 0 0 0 1px var(--hs-accent-pressed);
}
.hs-segmented__item:focus-visible {
  outline-offset: -2px;
}

/* ---- Waveform region (GUI_UX_SPEC §8: 96–120px standard) ---- */
.hs-waveform {
  grid-area: waveform;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 96px;
  min-height: 64px;
  max-height: 35vh;
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-compact);
}

/* ---- Score workspace + properties ---- */
.hs-main {
  grid-area: main;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  min-height: 0;
  min-width: 0;
}

.hs-score {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--hs-space-md);
  min-width: 0;
  min-height: 0;
  padding: var(--hs-space-lg);
  background: var(--hs-surface-score);
  color: var(--hs-text-primary);
  /* Score paper keeps a hairline radius, not decorative rounding (§7). */
  border-radius: var(--hs-radius-score-paper);
  overflow: auto;
}

.hs-properties {
  width: 264px;
  min-width: 200px;
  max-width: 320px;
  padding: var(--hs-space-md);
  background: var(--hs-surface-panel);
  border-left: 1px solid var(--hs-border-subtle);
  color: var(--hs-text-secondary);
  overflow: auto;
}
.hs-properties__title {
  margin: 0 0 var(--hs-space-sm);
  font-size: var(--hs-font-size-subtitle);
  font-weight: 600;
  color: var(--hs-text-primary);
}
.hs-properties__body {
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-muted);
}

/* §21 responsive: below 1200px the panel collapses to a drawer candidate. */
@media (max-width: 1199px) {
  .hs-properties {
    display: none;
  }
}

/* ---- Empty state (GUI_UX_SPEC §3, §19: compact, clear CTA) ---- */
.hs-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--hs-space-sm);
  text-align: center;
  max-width: 46em;
}
.hs-empty__title {
  margin: 0;
  font-size: var(--hs-font-size-display);
  font-weight: 400;
}
.hs-empty__or {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-caption);
}
.hs-empty__formats {
  margin: var(--hs-space-xs) 0 0;
  color: var(--hs-text-secondary);
  font-size: var(--hs-font-size-compact);
}
.hs-empty__privacy {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-caption);
}

/* ---- Transport (GUI_UX_SPEC §9) ---- */
.hs-transport {
  grid-area: transport;
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  height: 52px;
  padding: 0 var(--hs-space-ms);
  background: var(--hs-surface-panel);
  border-top: 1px solid var(--hs-border-subtle);
}
.hs-transport__time {
  font-variant-numeric: tabular-nums; /* §5: timecode uses tabular numerals */
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-secondary);
  margin-left: var(--hs-space-sm);
  white-space: nowrap;
}
.hs-transport__spacer {
  flex: 1 1 auto;
}

/* ---- Status bar ---- */
.hs-statusbar {
  grid-area: statusbar;
  display: flex;
  align-items: center;
  gap: var(--hs-space-md);
  height: 26px;
  padding: 0 var(--hs-space-ms);
  font-size: var(--hs-font-size-caption);
  color: var(--hs-text-muted);
  background: var(--hs-surface-panel);
  border-top: 1px solid var(--hs-border-subtle);
  user-select: none;
}
.hs-statusbar__message {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hs-statusbar__spacer {
  flex: 1 1 auto;
}

/* ====================== Primitives (components/primitives) ======================
   Only --hs-* semantic tokens; raw values live exclusively in tokens.css. */

/* ---- HsButton (§9): danger re-tints the primary fill to palette red ----
   Double-class selectors keep precedence over Fluent's atomic classes. */
.hs-button.hs-button--danger:not(:disabled) {
  background-color: var(--hs-danger);
  color: var(--hs-danger-foreground);
  border-color: transparent;
}
.hs-button.hs-button--danger:not(:disabled):hover {
  background-color: var(--hs-danger-hover);
}
.hs-button.hs-button--danger:not(:disabled):active {
  background-color: var(--hs-danger-pressed);
}
/* State changes use the fast motion tier (§18). */
.hs-button {
  transition-duration: var(--hs-motion-fast);
  transition-timing-function: var(--hs-ease-standard);
}

/* ---- Segmented control additions (§11, §17) ---- */
.hs-segmented__item:disabled {
  color: var(--hs-text-disabled);
  cursor: not-allowed;
}
.hs-segmented__item:disabled:hover {
  background: transparent;
}
.hs-segmented__item {
  transition: background-color var(--hs-motion-fast) var(--hs-ease-standard);
}

/* ---- StatusBadge / ReviewBadge (§15): tint + glyph + (review) dotted cue ---- */
.hs-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--hs-space-xs);
  padding: 1px var(--hs-space-sm);
  border-radius: var(--hs-radius-input);
  border: 1px solid transparent;
  font-size: var(--hs-font-size-caption);
  line-height: var(--hs-line-height-caption);
  font-weight: var(--hs-font-weight-emphasis);
  white-space: nowrap;
  user-select: none;
}
.hs-badge__icon {
  display: inline-flex;
  font-size: 14px;
}
.hs-badge--neutral {
  color: var(--hs-text-secondary);
  background: var(--hs-status-neutral-subtle);
  border-color: color-mix(in srgb, currentColor 25%, transparent);
}
.hs-badge--info {
  color: var(--hs-status-info);
  background: var(--hs-status-info-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
.hs-badge--success {
  color: var(--hs-status-success);
  background: var(--hs-status-success-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
.hs-badge--warning {
  color: var(--hs-status-warning);
  background: var(--hs-status-warning-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
.hs-badge--error {
  color: var(--hs-status-error);
  background: var(--hs-status-error-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
/* §15: the 要確認 marker adds a dotted underline — review is never red. */
.hs-badge--needs-review .hs-badge__label {
  border-bottom: 2px dotted var(--hs-review-marker);
}

/* ---- HsPanel (§8): flat separation by border; elevated for floats ---- */
.hs-panel {
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: var(--hs-surface-panel);
  border: 1px solid var(--hs-border-subtle);
  border-radius: var(--hs-radius-panel);
  color: var(--hs-text-primary);
}
.hs-panel--elevated {
  background: var(--hs-surface-elevated);
  box-shadow: var(--hs-elevation-popover);
}
.hs-panel__header {
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  padding: var(--hs-space-sm) var(--hs-space-ms);
  border-bottom: 1px solid var(--hs-border-subtle);
  min-height: 40px;
}
.hs-panel__title {
  margin: 0;
  font-size: var(--hs-font-size-subtitle);
  line-height: var(--hs-line-height-subtitle);
  font-weight: var(--hs-font-weight-title);
}
.hs-panel__header-spacer {
  flex: 1 1 auto;
}
.hs-panel__body {
  padding: var(--hs-space-md);
  min-width: 0;
}
.hs-panel__body--flush {
  padding: 0;
}

/* ---- HsSlider: track + tabular readout (§5) ---- */
.hs-slider {
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
}
.hs-slider .fui-Slider {
  flex: 1 1 auto;
}
.hs-slider__value {
  flex: 0 0 auto;
  min-width: 3.5em;
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-size: var(--hs-font-size-compact);
  line-height: var(--hs-line-height-compact);
  color: var(--hs-text-secondary);
}

/* ---- Settings (auxiliary screen, §18): replaces the workspace rows ---- */
.hs-settings-wrap {
  grid-row: commandbar / transport; /* spans commandbar…main rows */
  display: flex;
  min-height: 0;
  min-width: 0;
}
.hs-settings {
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
  padding: var(--hs-space-lg);
  background: var(--hs-surface-app);
  overflow: auto;
}
.hs-settings__title {
  margin: 0 0 var(--hs-space-md);
  font-size: var(--hs-font-size-title);
  font-weight: 600;
}
/* Section chrome (border / radius / padding) comes from the HsPanel
   primitive; this class only constrains width and rhythm. */
.hs-settings__section {
  margin: 0 0 var(--hs-space-lg);
  max-width: 560px;
}
.hs-settings__note {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-compact);
}
